preConditionHook:
// IS PRICE AT A MEASURED-MOVE TARGET? A gate, ANDed with whatever entry rule
// supplies the second reason -- Brooks's p78 caveat is that being at a measured
// move is not by itself a reason to trade. R08-14 allows countertrend entries
// only in the measured-move area; T03-17 uses the level as a two-sided band;
// T22-06 is the same test used to BLOCK with-trend entries near the target,
// which is this filter negated by the per-placement toggle, not a second rule.
//
// THE PROJECTION. The pattern is the refBars bars ENDING refOffset BARS AGO and
// the target is its far extreme plus multiple x its own height. refOffset is why
// the rule can ever fire and is not in the merged parameter list: with the
// window ending one bar ago its own extreme tracks the market, and price could
// only be a measured move beyond it after a single bar spanning the whole
// pattern height. Ending the window refOffset bars back leaves room to travel
// the measured distance while the level stands still. Optimizer input; 10 is
// half the default pattern.
//
// THE TOLERANCE is an ATR fraction, R08-14's own form, rather than T03-17's tick
// count -- the engine exposes no tick size to strategies.
//
// SIDES ARE MIRRORED: each side reads the measured-move target in its OWN
// direction. Plain on a with-trend long it is "take the breakout only into the
// target"; negated it is T22-06's block. A countertrend fade AT the bull target
// is a short taken on the long side's level, which one side alone cannot say.
//
// The Extremes loops are seeded on the window's first bar (index refOffset) and
// scan the rest with the tolerance-carrying strict comparison, mirroring EL's
// Extremes source.
mmHi = high[(int)refOffset];
mmLo = low[(int)refOffset];
for (int i = (int)refOffset + 1; i <= (int)refOffset + (int)refBars - 1; ++i) {
    if (el_gt(high[i], mmHi)) mmHi = high[i];
    if (el_lt(low[i], mmLo)) mmLo = low[i];
}
mmTgtUp = mmHi + multiple * (mmHi - mmLo);
mmTgtDn = mmLo - multiple * (mmHi - mmLo);
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget and ChannelLineTargetExit. Seeded with a full sum on the first
// calculated bar or when the length changes, and updated thereafter as TWO statements --
// EL evaluates S[1] + in - out left to right, and folding it to S += in - out
// rounds differently. atrLen is the local length counter; atrLookback the input.
if (atrLen != (int)atrLookback) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLookback; ++i) {
        double hiI = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double loI = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hiI - loI;
    }
    atrLen = (int)atrLookback;
} else {
    const int outBar = (int)atrLookback;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[outBar] > close[outBar + 1] ? high[outBar] : close[outBar + 1];
    double loOut = low[outBar] < close[outBar + 1] ? low[outBar] : close[outBar + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLookback;
